export const CALIBRATION_RECORD_8X = Object.freeze({ budget: 1190400, stepsPerJob: 384, seed: 310013,
  selectedSeed: 310013, keys: 775, cells: CELLS_8X });

/**
 * The record flattened, with the movement pulled out of the key.
 *
 * The movement is the first field of the `movement+action+effector+target`
 * grammar `plannedTacticKey` writes and `tactical-model.ts` declares as part of
 * the model contract, so reading it back out here is reading the contract rather
 * than parsing a string.
 */
export const calibrationRecordRows = () => Object.entries(CALIBRATION_RECORD_8X.cells)
  .flatMap(([cell, tactics]) => Object.entries(tactics).map(([tactic, [reachError, contactRateError, vitalityDeltaError]]) =>
    Object.freeze({ cell, tactic, movement: tactic.split("+")[0],
      calibration: Object.freeze({ reachError, contactRate: 0, contactRateError, vitalityDeltaError }) })));

/**
 * Which keys a set of limits admits, through the deployed rule itself rather
 * than a second copy of it.
 *
 * `calibrationRefusal` is what the beam and the runtime both ask, so a test that
 * reimplemented the three comparisons here could go green against a gate that
 * had stopped reading a column -- which is the defect the record exists to
 * catch. The record is loaded into a one-cell-per-body `TacticalModel` shape and
 * asked the real question.
 */
export const admittedByLimits = (refusal, limits) => calibrationRecordRows()
  .filter((row) => refusal({ cells: { [row.cell]: { [row.tactic]: { calibration: row.calibration } } }, tactics: {} },
    row.tactic, row.cell, limits) === null);
